  `system_version` varchar(64) DEFAULT NULL,
  `deployment_model` varchar(16) DEFAULT NULL,
  `inbound_transport` varchar(16) NOT NULL,
  `interface_notes` text DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'draft',
