  `credentials` text DEFAULT NULL,
  `inbound_key_prefix` varchar(16) DEFAULT NULL,
  `inbound_key_hash` char(64) DEFAULT NULL,
  `inbound_key_rotated_at` datetime DEFAULT NULL,
  `signing_secret` text DEFAULT NULL,
  `rate_limit_per_minute` smallint(5) unsigned NOT NULL DEFAULT 120,
  `last_message_at` datetime DEFAULT NULL,
  `last_processed_at` datetime DEFAULT NULL,
  `last_failure_at` datetime DEFAULT NULL,
  `last_error` varchar(255) DEFAULT NULL,
  `last_transfer_at` datetime DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `integration_connectors_organization_id_code_unique` (`organization_id`,`code`),
  UNIQUE KEY `integration_connectors_inbound_key_prefix_unique` (`inbound_key_prefix`),
  KEY `integration_connectors_created_by_foreign` (`created_by`),
  KEY `integration_connectors_organization_id_status_index` (`organization_id`,`status`),
  CONSTRAINT `integration_connectors_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `integration_connectors_organization_id_foreign` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `integration_external_references` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
