  CONSTRAINT `integration_field_mappings_organization_id_foreign` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `integration_inbox` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` char(26) NOT NULL,
  `connector_id` char(26) NOT NULL,
  `run_id` char(26) DEFAULT NULL,
  `message_id` varchar(128) NOT NULL,
  `entity_type` varchar(32) NOT NULL,
  `schema_version` smallint(5) unsigned NOT NULL DEFAULT 1,
  `payload_hash` char(64) NOT NULL,
