  `received_at` datetime NOT NULL,
  `processing_started_at` datetime DEFAULT NULL,
  `processed_at` datetime DEFAULT NULL,
  `resolved_by` bigint(20) unsigned DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  `resolution_notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `integration_inbox_connector_id_message_id_unique` (`connector_id`,`message_id`),
  KEY `integration_inbox_run_id_foreign` (`run_id`),
  KEY `integration_inbox_resolved_by_foreign` (`resolved_by`),
  KEY `integration_inbox_organization_id_status_received_at_index` (`organization_id`,`status`,`received_at`),
  KEY `integration_inbox_connector_id_status_index` (`connector_id`,`status`),
  KEY `integration_inbox_status_next_attempt_at_index` (`status`,`next_attempt_at`),
  CONSTRAINT `integration_inbox_connector_id_foreign` FOREIGN KEY (`connector_id`) REFERENCES `integration_connectors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `integration_inbox_organization_id_foreign` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `integration_inbox_resolved_by_foreign` FOREIGN KEY (`resolved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `integration_inbox_run_id_foreign` FOREIGN KEY (`run_id`) REFERENCES `integration_runs` (`id`) ON DELETE SET NULL
