  `recorded_at` datetime NOT NULL,
  `actor_user_id` bigint(20) unsigned DEFAULT NULL,
  `source_system` varchar(64) NOT NULL DEFAULT 'platform',
  `country_code` char(2) DEFAULT NULL,
  `corrects_event_id` char(26) DEFAULT NULL,
  `reverses_event_id` char(26) DEFAULT NULL,
  `correction_reason` text DEFAULT NULL,
  `details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`details`)),
  `prev_hash` char(64) DEFAULT NULL,
  `hash` char(64) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `trace_events_organization_id_sequence_unique` (`organization_id`,`sequence`),
  KEY `trace_events_batch_id_foreign` (`batch_id`),
  KEY `trace_events_actor_user_id_foreign` (`actor_user_id`),
  KEY `trace_events_lot_index` (`product_id`,`batch_number`,`event_time`),
  KEY `trace_events_organization_id_event_time_index` (`organization_id`,`event_time`),
  KEY `trace_events_source_organization_id_index` (`source_organization_id`),
  KEY `trace_events_destination_organization_id_index` (`destination_organization_id`),
  KEY `trace_events_related_type_related_id_index` (`related_type`,`related_id`),
  CONSTRAINT `trace_events_actor_user_id_foreign` FOREIGN KEY (`actor_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `trace_events_batch_id_foreign` FOREIGN KEY (`batch_id`) REFERENCES `batches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `trace_events_destination_organization_id_foreign` FOREIGN KEY (`destination_organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `trace_events_organization_id_foreign` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `trace_events_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `trace_events_source_organization_id_foreign` FOREIGN KEY (`source_organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `trace_identifiers` (
  `id` char(26) NOT NULL,
  `organization_id` char(26) NOT NULL,
  `kind` varchar(12) NOT NULL,
  `token` varchar(32) NOT NULL,
  `product_id` char(26) DEFAULT NULL,
  `gtin` varchar(14) DEFAULT NULL,
  `batch_number` varchar(64) DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `serial` varchar(64) DEFAULT NULL,
  `parent_id` char(26) DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'active',
  `status_reason` varchar(255) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `trace_identifiers_token_unique` (`token`),
  UNIQUE KEY `trace_identifiers_gtin_serial_unique` (`gtin`,`serial`),
